                let form = car(forms);
                let file = datum_file(form);
                let start = datum_pos(form);
                let kd = reads_key(v, r, form, fnv_string(str_lit!("check"), fnv_offset()));
                let key = fnv_string(car(texts), keyed_key(kd));
                let hit = memo_find(old, key);
